                bbox=(min(rs),max(rs),min(cs),max(cs))
                if ok and len(comp)>=4 and bbox[1]-bbox[0]>=2 and bbox[3]-bbox[2]>=2:
                    frames.append((v,(bbox)))
                else:
                    strpts.extend(comp)
    info={}
    for col in sorted(set(g[p[0]][p[1]] for p in strpts)):
