            ms=max(abs(p[0]-q[0])+abs(p[1]-q[1]) for p in pts for q in pts)
        else:
            ms=0
        info[col]=(ms,len(pts))
    out=[row[:] for row in g]
    framed=sorted(frames,key=lambda f:(f[1][0],f[1][2]))
