def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; frs=[]; strpts=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c] and g[r][c]!=bg:
                v=g[r][c]; st=[(r,c)]; comp=[]; seen[r][c]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=a+dy,b+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==v:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[p[0] for p in comp]; cc=[p[1] for p in comp]
                ok=all(r==min(rs) or r==max(rs) or c==min(cc) or c==max(cc) for r,c in comp)
                if ok and len(comp)>=4 and max(rs)-min(rs)>=2 and max(cc)-min(cc)>=2:
                    frs.append((v,min(rs),min(cc),max(rs),max(cc)))
                else:
                    strpts.extend(comp)
    # frame size = interior cell count
    def size(f): return (f[3]-f[1]-1)*(f[4]-f[2]-1)
    frs.sort(key=size)
    sc=Counter(g[p[0]][p[1]] for p in strpts)
    cols=sorted(sc,key=sc.get)  # least frequent first -> smaller frame
    out=[row[:] for row in g]
    for idx,(v,r0,c0,r1,c1) in enumerate(frs):
        ir,ic=r0+1,c0+1; r2,c2=r1-1,c1-1
        col=cols[idx%2]
        for dr in range(r2-ir+1):
            for dc in range(c2-ic+1):
                if (dr+dc)%2==0:
                    out[ir+dr][ic+dc]=col
    for r,c in set(strpts):
        out[r][c]=bg
    return out
